import type { HTMLAttributes } from "react";
import { cx } from "../utils/cx";

export type SeparatorProps = HTMLAttributes<HTMLDivElement> & {
  orientation?: "horizontal" | "vertical";
  /** Purely visual (no semantics). Default true; set false when the line separates meaningful groups. */
  decorative?: boolean;
};

/** A hairline between groups. Server-compatible. */
export function Separator({ orientation = "horizontal", decorative = true, className, ...rest }: SeparatorProps) {
  return (
    <div
      {...rest}
      role={decorative ? "none" : "separator"}
      aria-orientation={decorative ? undefined : orientation}
      className={cx("hm-separator", className)}
      data-orientation={orientation}
    />
  );
}
